// ZIZ Reminder Checker — runs every 1 minute
// Fetches due reminders from PostgreSQL and sends Telegram

const { Pool } = require('pg');

const pool = new Pool({
  host: '{{$vars.DB_HOST || "postgres"}}',
  port: {{$vars.DB_PORT || 5432}},
  database: '{{$vars.DB_NAME || "ziz_agent"}}',
  user: '{{$vars.DB_USER || "ziz"}}',
  password: '{{$vars.DB_PASSWORD}}',
});

const tg_token = '{{$vars.TG_TOKEN}}';

async function main() {
  const client = await pool.connect();
  try {
    // Get due reminders
    const res = await client.query(
      "SELECT id, chat_id, message FROM reminders WHERE sent = 0 AND remind_at <= NOW() ORDER BY remind_at ASC"
    );

    if (res.rows.length === 0) {
      return [{ result: 'no_reminders' }];
    }

    const results = [];
    for (const row of res.rows) {
      try {
        // Send Telegram message
        var tgResp = await this.helpers.request({
          method: 'POST',
          uri: 'https://api.telegram.org/bot' + tg_token + '/sendMessage',
          body: {
            chat_id: String(row.chat_id),
            text: '🔔 *Rappel ZIZ:*\\n' + (row.message || ''),
            parse_mode: 'Markdown'
          },
          json: true
        });

        if (tgResp && tgResp.ok) {
          // Mark as sent
          await client.query("UPDATE reminders SET sent = 1, sent_at = NOW() WHERE id = $1", [row.id]);
          results.push({ id: row.id, chat_id: row.chat_id, ok: true });
        }
      } catch(e) {
        results.push({ id: row.id, error: e.message || 'Unknown' });
      }
    }
    return results;
  } finally {
    client.release();
    await pool.end();
  }
}

return await main();
